// Small opt-in run HUD; free driving keeps its existing uncluttered screen.
export class SkillRunUI{
 constructor({run,onStart,onCruise}){
  this.run=run;this.onStart=onStart;this.onCruise=onCruise;this.clock=0;this.resultShown=false;
  const link=document.createElement('link');link.rel='stylesheet';link.href='skill-run.css';document.head.append(link);
  const start=document.createElement('button');start.id='home-rush';start.className='rush-start';start.innerHTML='<span>60 SECOND RUSH</span><small>DRIVE. CHAIN. BEAT YOUR BEST. ↗</small>';start.onclick=onStart;document.querySelector('.home-nav').before(start);
  const pauseStart=document.createElement('button');pauseStart.id='pause-rush';pauseStart.className='pause-action-btn';pauseStart.textContent='60 second Rush ↗';pauseStart.onclick=onStart;document.querySelector('#race').before(pauseStart);
  const hud=document.createElement('aside');hud.id='rush-hud';hud.hidden=true;hud.setAttribute('aria-label','60 second Rush');hud.innerHTML='<div class="rush-topline"><b>RUSH<small id="rush-target"></small></b><span id="rush-timer">60.0</span><strong id="rush-score">0</strong></div><div class="rush-progress" role="progressbar" aria-label="Run time remaining" aria-valuemin="0" aria-valuemax="60"><i></i></div><div class="rush-chain"><button id="rush-bank" aria-label="Bank skill chain"><strong id="rush-chain">GET READY</strong><small>B / TAP TO BANK</small></button><span id="rush-mult">×1</span></div><p id="rush-hint">Drive fast · Link drifts and near misses · Stay clean</p>';document.body.append(hud);this.hud=hud;
  this.target=hud.querySelector('#rush-target');this.timer=hud.querySelector('#rush-timer');this.score=hud.querySelector('#rush-score');this.chain=hud.querySelector('#rush-chain');this.mult=hud.querySelector('#rush-mult');this.bar=hud.querySelector('i');this.progress=hud.querySelector('[role="progressbar"]');this.hint=hud.querySelector('#rush-hint');this.bankButton=hud.querySelector('#rush-bank');this.bankButton.onclick=()=>{if(run.phase==='running'){run.bank();this.clock=0;this.update(0,false);}this.bankButton.blur();};
  const result=document.createElement('section');result.id='rush-result';result.className='rush-result';result.hidden=true;result.setAttribute('role','dialog');result.setAttribute('aria-modal','true');result.setAttribute('aria-labelledby','rush-result-title');result.innerHTML='<div class="rush-result-card"><span class="rush-eyebrow">60 SECOND RUSH / RESULTS</span><h2 id="rush-result-title">RUN COMPLETE</h2><strong id="rush-final-score">0</strong><p id="rush-record"></p><div id="rush-stats" class="rush-stats"></div><p id="rush-next"></p><div class="rush-result-actions"><button id="rush-again">RUN IT BACK ↗</button><button id="rush-cruise">FREE DRIVE</button></div><small>R / ENTER TO RETRY · ESC TO FREE DRIVE</small></div>';document.body.append(result);this.result=result;
  result.querySelector('#rush-again').onclick=onStart;result.querySelector('#rush-cruise').onclick=onCruise;
  this.keyHandler=e=>{if(e.key.toLowerCase()==='b'&&run.phase==='running'&&!this.hud.hidden){e.preventDefault();e.stopImmediatePropagation();if(!e.repeat)this.bankButton.click();return;}if(result.hidden)return;if(['Enter','r','R','Escape'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();if(e.repeat)return;e.key==='Escape'?onCruise():onStart();}};
  // Capture prevents the normal R/reset and Enter/sprint handlers from firing too.
  addEventListener('keydown',this.keyHandler,true);
 }
 showResult(){const r=this.run.result;if(!r||this.resultShown)return;this.resultShown=true;this.result.hidden=false;this.result.dataset.medal=r.medal.toLowerCase();this.result.querySelector('h2').textContent=r.medal==='ROOKIE'?'FIRST RUN IN THE BOOKS':r.medal+' RUN';this.result.querySelector('#rush-final-score').textContent=r.score.toLocaleString('en-US');this.result.querySelector('#rush-record').textContent=(r.newBest?'NEW PERSONAL BEST · ':'PERSONAL BEST · ')+r.best.toLocaleString('en-US');
  const stats=this.result.querySelector('#rush-stats');stats.replaceChildren();for(const [label,value]of [['BEST CHAIN',r.maxChain.toLocaleString('en-US')],['NEAR MISSES',r.nearMisses],['DRIFT TIME',r.driftSeconds.toFixed(1)+'s'],['TOP SPEED',r.topSpeed+' km/h']]){const item=document.createElement('div'),v=document.createElement('strong'),l=document.createElement('span');v.textContent=value;l.textContent=label;item.append(v,l);stats.append(item);}
  const next=this.run.rules.medals.find(n=>n>r.score);this.result.querySelector('#rush-next').textContent=next?`${(next-r.score).toLocaleString('en-US')} more points to the next medal. Link skills to build up to ×5.`:'GOLD SECURED. Can you beat your best chain?';this.result.querySelector('#rush-again').focus();
 }
 hideResult(){this.result.hidden=true;this.resultShown=false;}
 update(dt,paused){const run=this.run;this.hud.hidden=paused||!run.active;if(run.phase!=='finished'&&this.resultShown)this.hideResult();if(!run.active)return;this.clock-=dt;if(this.clock>0)return;this.clock=.1;
  const countdown=run.phase==='countdown',seconds=countdown?String(Math.ceil(run.countdown)):run.remaining.toFixed(1),score=run.score.toLocaleString('en-US'),chain=countdown?'GET READY · '+seconds:run.chain>0?Math.round(run.chain*run.mult).toLocaleString('en-US')+' TO BANK':run.notice,mult='×'+run.mult;
  const tier=run.rules.medals.findIndex(n=>run.score<n);this.target.textContent=tier<0?'GOLD SECURED':['BRONZE','SILVER','GOLD'][tier]+' '+run.rules.medals[tier].toLocaleString('en-US');this.timer.textContent=countdown?'READY':seconds;this.score.textContent=score;this.chain.textContent=chain;this.mult.textContent=mult;this.bankButton.disabled=countdown||run.chain<=0;this.hint.textContent=countdown?'Drive fast · Drift anywhere · Pass traffic cleanly':run.chain>0&&run.time>=run.noticeUntil?'BANK NOW OR KEEP CHAINING FOR ×5':run.notice;
  this.bar.style.transform=`scaleX(${run.remaining/60})`;this.progress.setAttribute('aria-valuenow',String(Math.ceil(run.remaining)));this.hud.classList.toggle('rush-last-seconds',!countdown&&run.remaining<=10);
 }
}
